/* @lc app=leetcode id=3768 lang=kotlin */ class Solution { fun ad(t: IntArray, i0: Int, d: Int) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += d } fun qs(t: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun minInversionCount(nums: IntArray, k: Int): Long = nums.toSet().sorted().let { vs -> IntArray(vs.size + 1).let { bit -> nums.indices.fold(0L to Long.MAX_VALUE) { (inv, best), i -> (if (i >= k) ad(bit, vs.binarySearch(nums[i - k]) + 1, -1).let { inv - qs(bit, vs.binarySearch(nums[i - k])) } else inv).let { inv2 -> (vs.binarySearch(nums[i]) + 1).let { r -> (inv2 + ((if (i >= k) k - 1 else i) - qs(bit, r))).let { inv3 -> ad(bit, r, 1).let { inv3 to (if (i >= k - 1) minOf(best, inv3) else best) } } } } }.second } } }